-- Create a function to send email notification for new users
CREATE OR REPLACE FUNCTION notify_new_user()
RETURNS TRIGGER AS $$
DECLARE
  user_email TEXT;
  user_id_text TEXT;
BEGIN
  -- Get the user's email
  user_email := NEW.email;
  user_id_text := NEW.id::TEXT;

  -- Log the new user creation
  RAISE LOG 'New user created: % (ID: %)', user_email, user_id_text;

  -- Insert into notification queue table
  INSERT INTO new_user_notifications (user_id, user_email, created_at)
  VALUES (NEW.id, user_email, NOW());

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Drop trigger if exists and create new one
DROP TRIGGER IF EXISTS on_new_user_created ON auth.users;
CREATE TRIGGER on_new_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW
  EXECUTE FUNCTION notify_new_user();

-- Create an index for faster queries
CREATE INDEX IF NOT EXISTS idx_new_user_notifications_notified 
  ON new_user_notifications(notification_sent, created_at);

